CREATE TABLE public.delivery_addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.pdv_customers(id),address jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.delivery_addresses TO authenticated; GRANT ALL ON public.delivery_addresses TO service_role; ALTER TABLE public.delivery_addresses ENABLE ROW LEVEL SECURITY; CREATE POLICY address_admin_read ON public.delivery_addresses FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.delivery_couriers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,phone text NOT NULL DEFAULT '',user_id uuid UNIQUE,active boolean NOT NULL DEFAULT true); GRANT SELECT ON public.delivery_couriers TO authenticated; GRANT ALL ON public.delivery_couriers TO service_role; ALTER TABLE public.delivery_couriers ENABLE ROW LEVEL SECURITY; CREATE POLICY courier_read ON public.delivery_couriers FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'cashier') OR public.has_role(auth.uid(),'operator') OR (user_id=auth.uid() AND public.has_role(auth.uid(),'courier')));
CREATE TABLE public.delivery_routes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,courier_id uuid REFERENCES public.delivery_couriers(id),origin text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),created_by uuid,distance_meters numeric,duration_seconds numeric); GRANT SELECT ON public.delivery_routes TO authenticated; GRANT ALL ON public.delivery_routes TO service_role; ALTER TABLE public.delivery_routes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.delivery_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id text NOT NULL UNIQUE,customer_id uuid REFERENCES public.pdv_customers(id),customer text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',address jsonb NOT NULL DEFAULT '{}',payment_method text NOT NULL DEFAULT 'Pix',cash_for numeric NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz,status text NOT NULL DEFAULT 'Aguardando preparo' CHECK(status IN ('Aguardando preparo','Pronto para entrega','Em rota','Entregue','Cancelado')),route_id uuid REFERENCES public.delivery_routes(id),position integer NOT NULL DEFAULT 0,problem text); GRANT SELECT ON public.delivery_orders TO authenticated; GRANT ALL ON public.delivery_orders TO service_role; ALTER TABLE public.delivery_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY route_read ON public.delivery_routes FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR ((public.has_role(auth.uid(),'cashier') OR public.has_role(auth.uid(),'operator')) AND EXISTS(SELECT 1 FROM public.delivery_orders d WHERE d.route_id=delivery_routes.id AND d.status NOT IN ('Entregue','Cancelado'))) OR (public.has_role(auth.uid(),'courier') AND EXISTS(SELECT 1 FROM public.delivery_couriers c WHERE c.id=delivery_routes.courier_id AND c.user_id=auth.uid() AND c.active)));
CREATE POLICY delivery_read ON public.delivery_orders FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR ((public.has_role(auth.uid(),'cashier') OR public.has_role(auth.uid(),'operator')) AND status NOT IN ('Entregue','Cancelado')) OR (public.has_role(auth.uid(),'courier') AND EXISTS(SELECT 1 FROM public.delivery_routes r JOIN public.delivery_couriers c ON c.id=r.courier_id WHERE r.id=delivery_orders.route_id AND c.user_id=auth.uid() AND c.active)));
CREATE INDEX delivery_pending_idx ON public.delivery_orders(status,created_at); CREATE INDEX delivery_route_idx ON public.delivery_orders(route_id,position);